MOTIF_NAME = 'knight_attacking_king_zone'
MOTIF_DESCRIPTION = 'The side to move has a knight attacking squares near the opponent king while the opponent has no equivalent attack.'
def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False

    king_zone = []
    for sq in chess.SQUARES:
        if chess.square_distance(opp_king_sq, sq) <= 2:
            king_zone.append(sq)

    stm_knights = board.pieces(chess.KNIGHT, stm)
    stm_attacks = 0
    for knight_sq in stm_knights:
        for target in chess.SQUARES:
            if target in king_zone:
                if target in board.attacks(knight_sq):
                    piece = board.piece_at(target)
                    if piece is None or piece.color == opp:
                        stm_attacks += 1

    stm_king_sq = board.king(stm)
    if stm_king_sq is None:
        return False
    stm_king_zone = []
    for sq in chess.SQUARES:
        if chess.square_distance(stm_king_sq, sq) <= 2:
            stm_king_zone.append(sq)

    opp_knights = board.pieces(chess.KNIGHT, opp)
    opp_attacks = 0
    for knight_sq in opp_knights:
        for target in chess.SQUARES:
            if target in stm_king_zone:
                if target in board.attacks(knight_sq):
                    piece = board.piece_at(target)
                    if piece is None or piece.color == stm:
                        opp_attacks += 1

    return stm_attacks > opp_attacks
